    (
        'function renderCmdChart(){\n  const container=document.getElementById(\'acc-chart\');\n  if(!container || !window._cmdCoin) return;\n  if(!container.querySelector(\'#cmd-chart-box\')){\n    container.innerHTML = `\n      <div id="cmd-chart-box" style="background:#040408;height:180px;border:1px solid #1e1e2e;border-radius:2px;margin-bottom:5px;overflow:hidden"></div>\n      <div id="cmd-chart-status" style="font-size:9px;color:#666;margin-bottom:8px"></div>\n      <button onclick="loadCoin(window._cmdCoin)" style="width:100%;padding:6px;background:#0a0a14;border:1px solid #333;color:#aaa;border-radius:2px;font-size:10px;cursor:pointer">Open full Sniper view →</button>\n    `;\n  }\n  const box=document.getElementById(\'cmd-chart-box\');\n  if(!window._cmdChart && box && typeof LightweightCharts!==\'undefined\'){\n',
        '/* ── Reusable scalping chart widget (candles + EMA9/21 + VWAP + Pivot\n   S/R lines + candle countdown + Multi-TF RSI strip). Each instance\n   keeps its own chart/series objects in a closure — no global collision\n   between the two Command-tab widgets (BTC-fixed + manual coin). ── */\nfunction createScalpChartWidget(containerId, opts){\n  opts = opts || {};\n  const idPrefix = opts.idPrefix;\n  const fixedSymbol = opts.fixedSymbol || null;\n  const container = document.getElementById(containerId);\n  if(!container) return null;\n\n  let currentSymbol = fixedSymbol || \'BTCUSDT\';\n  let tf = \'15m\';\n  let pivotBasis = \'daily\';\n  let chart=null, candleSeries=null, ema9Series=null, ema21Series=null, vwapSeries=null;\n  let pivotLines=[];\n  const TF_LIST=[\'1m\',\'5m\',\'15m\',\'1h\',\'4h\',\'8h\',\'1d\'];\n  const TF_SECONDS={\'1m\':60,\'5m\':300,\'15m\':900,\'1h\':3600,\'4h\':14400,\'8h\':28800,\'1d\':86400};\n\n  const searchHtml = fixedSymbol ? \'\' : `\n    <div style="display:flex;gap:4px;margin-bottom:6px">\n      <input id="${idPrefix}-inp" type="text" placeholder="Coin e.g. ETH" value="BTC" style="flex:1;background:#0a0a14;border:1px solid #333;color:#fff;padding:4px 6px;font-size:10px;border-radius:2px">\n      <button onclick="window.__scalpWidgets[\'${idPrefix}\'].search()" style="background:#003311;border:1px solid #00ff88;color:#00ff88;padding:4px 10px;font-size:9px;border-radius:2px;cursor:pointer">Load</button>\n    </div>`;\n\n  container.innerHTML = `\n    ${searchHtml}\n    <div style="display:flex;gap:3px;margin-bottom:6px;flex-wrap:wrap">\n      ${TF_LIST.map(t=>`<button class="${idPrefix}-tf-btn" data-tf="${t}" onclick="window.__scalpWidgets[\'${idPrefix}\'].setTf(\'${t}\')" style="background:${t===\'15m\'?\'#003311\':\'#0a0a14\'};border:1px solid ${t===\'15m\'?\'#00ff88\':\'#333\'};color:${t===\'15m\'?\'#00ff88\':\'#aaa\'};padding:2px 6px;font-size:8px;cursor:pointer;border-radius:2px">${t}</button>`).join(\'\')}\n      <button onclick="window.__scalpWidgets[\'${idPrefix}\'].toggleMultiTf()" style="background:#1a0a2e;border:1px solid #a855f7;color:#c084fc;padding:2px 6px;font-size:8px;cursor:pointer;border-radius:2px;font-weight:bold">ALL</button>\n    </div>\n    <div style="position:relative;margin-bottom:6px">\n      <div id="${idPrefix}-box" style="background:#040408;height:220px;border:1px solid #1e1e2e;border-radius:2px;overflow:hidden"></div>\n      <div id="${idPrefix}-countdown" style="position:absolute;top:4px;right:6px;background:rgba(10,10,20,0.85);border:1px solid #333;border-radius:2px;padding:2px 6px;font-size:8px;color:var(--gold);z-index:5">⏱ —</div>\n    </div>\n    <div id="${idPrefix}-multitf" style="display:none;background:#0a0a14;border:1px solid #1e1e2e;border-radius:2px;padding:5px;margin-bottom:6px">\n      <div style="font-size:8px;color:var(--grey);margin-bottom:3px">RSI ACROSS TIMEFRAMES</div>\n      <div style="display:grid;grid-template-columns:repeat(7,1fr);gap:3px;text-align:center;font-size:8px">\n        ${TF_LIST.map(t=>`<div>${t}<br><span id="${idPrefix}-rsi-${t}">—</span></div>`).join(\'\')}\n      </div>\n    </div>\n    <div style="display:flex;gap:3px;margin-bottom:5px;align-items:center;flex-wrap:wrap">\n      <span style="font-size:8px;color:var(--grey)">PIVOT:</span>\n      <button id="${idPrefix}-pivot-daily" onclick="window.__scalpWidgets[\'${idPrefix}\'].setPivotBasis(\'daily\')" style="background:#003311;border:1px solid #00ff88;color:#00ff88;padding:1px 6px;font-size:8px;cursor:pointer;border-radius:2px">Daily</button>\n      <button id="${idPrefix}-pivot-hourly" onclick="window.__scalpWidgets[\'${idPrefix}\'].setPivotBasis(\'hourly\')" style="background:#0a0a14;border:1px solid #333;color:#aaa;padding:1px 6px;font-size:8px;cursor:pointer;border-radius:2px">Hourly</button>\n      <span id="${idPrefix}-conf" style="margin-left:auto;font-size:8px;color:var(--grey)">S/R Conf: —</span>\n    </div>\n    <div id="${idPrefix}-status" style="font-size:8px;color:#666"></div>\n  `;\n\n  function initChartInstance(){\n    const box=document.getElementById(idPrefix+\'-box\');\n    if(!box || typeof LightweightCharts===\'undefined\') return;\n',
    ),
