    (
        "      window._cmdCandleSeries=window._cmdChart.addCandlestickSeries({\n        upColor:'#00cc44',downColor:'#cc2200',\n        borderUpColor:'#00cc44',borderDownColor:'#cc2200',\n        wickUpColor:'#00cc44',wickDownColor:'#cc2200',\n",
        "      candleSeries=chart.addCandlestickSeries({upColor:'#00cc44',downColor:'#cc2200',borderUpColor:'#00cc44',borderDownColor:'#cc2200',wickUpColor:'#00cc44',wickDownColor:'#cc2200'});\n      ema9Series=chart.addLineSeries({color:'#00bfff',lineWidth:1,priceLineVisible:false,lastValueVisible:false});\n      ema21Series=chart.addLineSeries({color:'#ff9900',lineWidth:1,priceLineVisible:false,lastValueVisible:false});\n      vwapSeries=chart.addLineSeries({color:'#c084fc',lineWidth:1,lineStyle:2,priceLineVisible:false,lastValueVisible:false});\n    }catch(e){console.warn('Scalp chart widget init failed:',e);}\n  }\n\n  function load(){\n    const st=document.getElementById(idPrefix+'-status');\n    if(st) st.textContent='Loading '+currentSymbol+' '+tf+'...';\n    fetch(`/chart_data?symbol=${currentSymbol}&interval=${tf}&limit=50`).then(r=>r.json()).then(d=>{\n      if(!candleSeries || !d.candles || !d.candles.length){ if(st) st.textContent='No data for '+currentSymbol; return; }\n      const candles=d.candles.map(c=>({time:c.time,open:parseFloat(c.open),high:parseFloat(c.high),low:parseFloat(c.low),close:parseFloat(c.close)}));\n      candleSeries.setData(candles);\n      if(st) st.textContent=candles.length+' candles ('+currentSymbol+' '+tf+')';\n      try{\n        if(ema9Series) ema9Series.setData(calcEMASeries(candles,9));\n        if(ema21Series) ema21Series.setData(calcEMASeries(candles,21));\n        if(vwapSeries && d.vwap_line && d.vwap_line.length) vwapSeries.setData(d.vwap_line);\n      }catch(e){}\n      updatePivots(candles[candles.length-1].close);\n    }).catch(()=>{ if(st) st.textContent='Chart fetch failed'; });\n  }\n\n  function updatePivots(currentPrice){\n    fetch(`/pivot_points?symbol=${currentSymbol}&type=${pivotBasis}`).then(r=>r.json()).then(pv=>{\n      if(!candleSeries) return;\n      pivotLines.forEach(l=>{try{candleSeries.removePriceLine(l);}catch(e){}});\n      pivotLines=[];\n      const confEl=document.getElementById(idPrefix+'-conf');\n      if(!pv.available){ if(confEl) confEl.textContent='S/R Conf: no data'; return; }\n      const levels=[\n        {key:'s1',label:'S1',price:pv.s1,color:'#00ff88'},{key:'s2',label:'S2',price:pv.s2,color:'#00cc66'},{key:'s3',label:'S3',price:pv.s3,color:'#009944'},\n        {key:'r1',label:'R1',price:pv.r1,color:'#ff2244'},{key:'r2',label:'R2',price:pv.r2,color:'#dd1133'},{key:'r3',label:'R3',price:pv.r3,color:'#bb0022'},\n        {key:'pivot',label:'P',price:pv.pivot,color:'#ffd700'},\n      ];\n      let minDist=Infinity;\n      levels.forEach(lv=>{\n        if(!lv.price) return;\n        const distPct=currentPrice?Math.abs(currentPrice-lv.price)/currentPrice*100:100;\n        const near=distPct<=0.3;\n        const primary=['pivot','s1','r1'].includes(lv.key);\n        if(distPct<minDist) minDist=distPct;\n        const ln=candleSeries.createPriceLine({price:lv.price,color:lv.color,lineWidth:near?3:1,lineStyle:near?0:2,axisLabelVisible:near||primary,title:near?('🔥 '+lv.label):(primary?lv.label:'')});\n        pivotLines.push(ln);\n",
    ),
    (
        "    }catch(e){console.warn('Command chart init failed:',e);}\n",
        "      if(confEl){\n        const score=Math.max(0,Math.round(100-Math.min(minDist,5)*20));\n        confEl.textContent='S/R Conf: '+score+'%';\n        confEl.style.color=score>=70?'var(--green)':score>=40?'var(--gold)':'var(--grey)';\n      }\n    }).catch(()=>{});\n",
    ),
    (
        "  const st=document.getElementById('cmd-chart-status');\n  if(st) st.textContent='Loading '+window._cmdCoin+'...';\n  fetch(`/chart_data?symbol=${window._cmdCoin}&interval=15m&limit=50`).then(r=>r.json()).then(d=>{\n    if(!window._cmdCandleSeries || !d.candles || !d.candles.length){ if(st) st.textContent='No candle data'; return; }\n    const candles=d.candles.map(c=>({time:c.time,open:parseFloat(c.open),high:parseFloat(c.high),low:parseFloat(c.low),close:parseFloat(c.close)}));\n    window._cmdCandleSeries.setData(candles);\n    if(st) st.textContent=candles.length+' candles ('+window._cmdCoin+' 15m)';\n  }).catch(()=>{ if(st) st.textContent='Chart fetch failed'; });\n",
        '\n  function startCountdown(){\n    setInterval(()=>{\n      const el=document.getElementById(idPrefix+\'-countdown\');\n      if(!el) return;\n      const dur=TF_SECONDS[tf]||900;\n      const secs=dur-Math.floor((Date.now()/1000)%dur);\n      const m=Math.floor(secs/60), s=secs%60;\n      el.textContent=\'⏱ \'+(m>0?m+\'m \':\'\')+s+\'s\';\n    },1000);\n  }\n\n  const api = {\n    setTf(newTf){\n      tf=newTf;\n      document.querySelectorAll(\'.\'+idPrefix+\'-tf-btn\').forEach(b=>{\n        const on=b.dataset.tf===tf;\n        b.style.background=on?\'#003311\':\'#0a0a14\';\n        b.style.borderColor=on?\'#00ff88\':\'#333\';\n        b.style.color=on?\'#00ff88\':\'#aaa\';\n      });\n      load();\n    },\n    setPivotBasis(basis){\n      pivotBasis=basis;\n      const d=document.getElementById(idPrefix+\'-pivot-daily\'), h=document.getElementById(idPrefix+\'-pivot-hourly\');\n      const on={background:\'#003311\',borderColor:\'#00ff88\',color:\'#00ff88\'}, off={background:\'#0a0a14\',borderColor:\'#333\',color:\'#aaa\'};\n      if(d) Object.assign(d.style, basis===\'daily\'?on:off);\n      if(h) Object.assign(h.style, basis===\'hourly\'?on:off);\n      load();\n    },\n    search(){\n      const inp=document.getElementById(idPrefix+\'-inp\');\n      if(!inp) return;\n      const s=inp.value.toUpperCase().replace(/[^A-Z0-9]/g,\'\');\n      if(!s) return;\n      currentSymbol=s.includes(\'USDT\')?s:s+\'USDT\';\n      load();\n    },\n    toggleMultiTf(){\n      const strip=document.getElementById(idPrefix+\'-multitf\');\n      if(!strip) return;\n      const show=strip.style.display===\'none\';\n      strip.style.display=show?\'block\':\'none\';\n      if(show){\n        fetch(`/rsi_multi_tf?symbol=${currentSymbol}`).then(r=>r.json()).then(d=>{\n          const rsi=d.rsi||{};\n          TF_LIST.forEach(t=>{\n            const el=document.getElementById(idPrefix+\'-rsi-\'+t);\n            if(!el) return;\n            const v=rsi[t];\n            if(v===null||v===undefined){ el.textContent=\'—\'; el.style.color=\'var(--grey)\'; return; }\n            el.textContent=v;\n            el.style.color=v>=70?\'var(--red)\':v<=30?\'var(--green)\':\'var(--gold)\';\n          });\n        }).catch(()=>{});\n      }\n    },\n  };\n\n  window.__scalpWidgets = window.__scalpWidgets || {};\n  window.__scalpWidgets[idPrefix] = api;\n\n  setTimeout(()=>{ initChartInstance(); load(); startCountdown(); }, 50);\n  return api;\n}\n\nfunction renderCmdChart(){\n  const container=document.getElementById(\'acc-chart\');\n  if(!container) return;\n  if(container.querySelector(\'#cmd-btc-widget\')) return; // already built — widgets manage their own refresh\n  container.innerHTML = `\n    <div class="card" style="margin-bottom:8px">\n      <div class="ch" style="font-size:10px">₿ BTC Chart (fixed)</div>\n      <div class="cb" id="cmd-btc-widget"></div>\n    </div>\n    <div class="card">\n      <div class="ch" style="font-size:10px">🔍 Manual Coin Chart</div>\n      <div class="cb" id="cmd-manual-widget"></div>\n    </div>\n  `;\n  createScalpChartWidget(\'cmd-btc-widget\', {idPrefix:\'cmdbtc\', fixedSymbol:\'BTCUSDT\'});\n  createScalpChartWidget(\'cmd-manual-widget\', {idPrefix:\'cmdman\'});\n',
    ),
